namespace docking.util;






using generic.theme;
using generic.theme;

public class MessageOverlay : LayerUI<JComponent> {
	private string FONT_ID = "font.messageoverlay";
	private Color backgroundColor = new GColor("color.bg.messageoverlay");
	private Color textColor = new GColor("color.fg.messageoverlay");

	private string message = null;

	/* @Override */
	public void paint(Graphics g, JComponent c) {
		base.paint(g, c);
		if (message == null) {
			return;
		}

		Graphics2D g2 = (Graphics2D) g.create();

		g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, .60f));

		Font font = Gui.getFont(FONT_ID);
		g2.setFont(font);

		FontMetrics fm = g2.getFontMetrics(font);

		int bottomY = (int) (c.getY() + c.getHeight());

		int startX = 0;
		int startY = bottomY - 5;
		Color[] colors = { backgroundColor, new Color(0, 0, 0, 0) };

		int backgroundHeight = (fm.getHeight() * 3);
		int backgroundWidth = c.getWidth();
		int backgroundY = bottomY - backgroundHeight;

		float[] fractions = new float[] { 0.0f, .95f };
		int upperY = backgroundY;

		g2.setPaint(new LinearGradientPaint(new Point(startX, startY), new Point(startX, upperY),
			fractions, colors));
		g2.fillRect(startX, backgroundY, backgroundWidth, backgroundHeight);

		g2.setPaint(textColor);

		int centerX = (c.getWidth() - fm.stringWidth(message)) / 2;
		g2.drawString(message, centerX, startY);
	}

	public void setMessage(string message) {
		this.message = message;
	}
}
